                   type: "tel",
                   helperText: "Optional. Use digits, spaces, hyphens, parentheses, or a leading +.",
                   placeholder: "+1 (555) 123-4567",
                 })}
               </div>
               <div class="actions">
                 <button type="submit">Submit request</button>
               </div>
               <div class="status" id="form-status" role="status" aria-live="polite"></div>
             </form>
           </section>
         </main>
       `;

       document.getElementById("app").innerHTML = ContactForm();

       const form = document.getElementById("contact-form");
       const status = document.getElementById("form-status");
       const validators = {
         fullName: (value) => {
           if (!value.trim()) return "Full name is required.";
           if (value.trim().length < 2) return "Please enter a valid full name.";
           return "";
         },
         email: (value) => {
           if (!value.trim()) return "Email address is required.";
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           return emailPattern.test(value.trim()) ? "" : "Enter a valid email address.";
         },
         phone: (value) => {
           if (!value.trim()) return "";
           const phonePattern = /^\+?[0-9()\-\s.]{7,}$/;
           return phonePattern.test(value.trim()) ? "" : "Enter a valid phone number or leave it blank.";
         },
       };

       const setFieldState = (input) => {
         const fieldEl = input.closest(".form-field");
         const errorEl = document.getElementById(`${input.id}-error`);
         const message = validators[input.id](input.value);
         fieldEl.classList.toggle("invalid", Boolean(message));
         errorEl.textContent = message;
         input.setAttribute("aria-invalid", Boolean(message));
         return !message;
       };

       form.querySelectorAll("input").forEach((input) => {
         input.addEventListener("blur", () => setFieldState(input));
         input.addEventListener("input", () => {
           if (input.value.trim()) setFieldState(input);
           else {
             const fieldEl = input.closest(".form-field");
             const errorEl = document.getElementById(`${input.id}-error`);
             fieldEl.classList.remove("invalid");
             errorEl.textContent = "";
             input.removeAttribute("aria-invalid");
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const inputs = [...form.querySelectorAll("input")];
         const valid = inputs.map(setFieldState).every(Boolean);

         if (!valid) {
           status.textContent = "Please fix the highlighted fields and try again.";
           return;
         }

         status.textContent = "Your message is ready to send.";
         form.reset();
         inputs.forEach((input) => {
           input.removeAttribute("aria-invalid");
           input.closest(".form-field").classList.remove("invalid");
           document.getElementById(`${input.id}-error`).textContent = "";
         });
       });
     </script>
   </body>
 </html>

')
